import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(instance, properties):
    raw = execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': instance, 'properties': properties}))['returnValue']
    return json.loads(raw)

def list_props(instance):
    return execute_tool('editor_toolset.toolsets.object.ObjectTools.list_properties', json.dumps({'instance': instance}))['returnValue']

def run():
    return {
      'gameFeatureComponents': get({'refPath': '/ExtractionOps/ExtractionOps.ExtractionOps:GameFeatureAction_AddComponents_0'}, ['componentList']),
      'pawnData': get(load('/ExtractionOps/Pawns/DA_ExtractionPawnData'), ['abilitySets', 'inputConfig']),
      'rifleDamage': get(load('/ExtractionOps/Weapons/Rifle/GE_Damage_ExtractionRifle'), ['executions', 'modifiers', 'durationPolicy']),
      'shotgunDamage': get(load('/ExtractionOps/Weapons/Shotgun/GE_Damage_ExtractionShotgun'), ['executions', 'modifiers', 'durationPolicy']),
      'experience': get(load('/ExtractionOps/Experiences/B_ExtractionExperience'), ['actionSets', 'defaultPawnData', 'gameFeaturesToEnable']),
      'itemDefinitionClassProperties': list_props({'refPath': '/Script/ExtractionOpsRuntime.Default__ExtractionItemDefinition'}),
      'armorSetClassProperties': list_props({'refPath': '/Script/ExtractionOpsRuntime.Default__ExtractionArmorSet'})
    }
